using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpStdioServer;

[McpServerToolType]
public sealed class ApiFetchTool
{
    private readonly IHttpClientFactory _httpClientFactory;

    public ApiFetchTool(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    [McpServerTool("fetch_post"), Description("Fetches a post by ID from the JSONPlaceholder API.")]
    public async Task<string> FetchPost(
        [Description("The numeric post ID to retrieve (1-100).")] int postId)
    {
        using var client = _httpClientFactory.CreateClient("api");
        var response = await client.GetAsync($"/posts/{postId}");
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>();
        return JsonSerializer.Serialize(json, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace McpStdioServer;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize"), Description("Summarize the provided text into key bullet points.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text content to summarize.")] string text,
        [Description("Maximum number of bullet points (default 5).")] int? maxPoints = 5)
    {
        return
        [
            new()
            {
                Role = Role.User,
                Content = new Content
                {
                    Type = "text",
                    Text = $"""
                        Summarize the following text into at most {maxPoints ?? 5} concise bullet points.
                        Return only the bullet list, no preamble.

                        ---
                        {text}
                        """
                }
            }
        ];
    }
}

